  useEffect(() => { if (!projectId && projects.data?.length) { const project = projects.data.find(item => item.sourcesAttached); if (project) setProjectId(String(project.id)); } }, [projectId, projects.data]);
  const id = Number(projectId); const validProject = Number.isInteger(id) && id > 0; const input = useMemo(() => ({ projectId: id }), [id]); const review = trpc.timeline.review.useQuery(input, { enabled: validProject, retry: false }); const candidates = trpc.timeline.candidates.useQuery(input, { enabled: validProject && !!replaceTarget, retry: false });
  const refresh = async () => Promise.all([api.timeline.review.invalidate(input), api.worker.renderHandoff.invalidate(input)]);
  const approve = trpc.timeline.approve.useMutation({ onSuccess: async () => { await api.timeline.review.invalidate(input); toast.success("Timeline approved. Native handoff is unlocked."); }, onError: error => toast.error(error.message) });
