      const directionChip = (type: "IN" | "OUT", label: string) => `<button data-zoom-direction="${type}" class="rounded-md border px-2 py-1.5 text-left text-[10px] ${enabledDirections.includes(type) ? "border-cyan-200/60 bg-cyan-200/15 text-cyan-50" : "border-white/10 bg-black/15 text-slate-400"}">${label}</button>`;
