      const transition = target.dataset.transition as TransitionName | undefined; const direction = target.dataset.zoomDirection as "IN" | "OUT" | undefined;
      if (target.dataset.transitionNone) { selectedTransition = "NONE"; emit({ transitionType: "NONE", enabledTransitions, crossfadeDurationMs: duration as 300 | 500 | 800 | 1000 | 1200 }); render(); return; }
